<template>
  <AccountLayout bare><main class="po-page" :aria-busy="busy">
    <header class="po-header"><div class="po-heading"><FileMinus2 :size="30"/><div><h1>Sellers Debit Note</h1><p>All Sellers Debit Notes</p></div></div><div v-if="view==='list'" class="po-header-search"><Search/><input v-model="filters.search" placeholder="Search Debit Note No. / Invoice No. / PO No. / Seller..."></div><div class="po-actions"><button v-if="view==='detail'" class="po-btn" @click="back"><ArrowLeft/> Back to list</button><span v-if="view==='detail'" class="po-pill" :class="slug(form.status)">{{ form.status }}</span></div></header>
    <div v-if="error" class="po-alert error">{{ error }}</div><div v-if="notice" class="po-alert success">{{ notice }}</div>
    <template v-if="view==='list'">
      <section class="po-metrics"><article v-for="card in metrics" :key="card.label" :class="card.tone"><component :is="card.icon" :size="30"/><div><h2>{{ card.label }}</h2><strong>{{ card.rows.length }} <small>Debit Notes</small></strong><b>{{ money(sum(card.rows)) }} {{ currency(card.rows) }}</b></div></article></section>
      <form class="po-filters" @submit.prevent="page=1"><label>Date Range<span class="po-date-range"><input v-model="filters.from" type="date"><input v-model="filters.to" type="date"></span></label><label>Seller<select v-model="filters.seller"><option value="">All Sellers</option><option v-for="x in sellerNames" :key="x">{{ x }}</option></select></label><label>Status<select v-model="filters.status"><option value="">All Status</option><option v-for="x in statuses" :key="x">{{ x }}</option></select></label><label>Payment Status<select v-model="filters.settlement"><option value="">All Status</option><option v-for="x in settlementStatuses" :key="x">{{ x }}</option></select></label><label>Department<select v-model="filters.department"><option value="">All Departments</option><option v-for="x in departments" :key="x">{{ x }}</option></select></label><label>Project<select v-model="filters.project"><option value="">All Projects</option><option v-for="x in projects" :key="x">{{ x }}</option></select></label><button class="po-btn primary"><Search/> Search</button><button class="po-btn" type="button" @click="filters=initialFilters()"><RotateCcw/> Reset</button></form>
      <section class="po-list"><header class="po-section-head"><h2>Sellers Debit Note List</h2><div class="po-actions"><button class="po-btn primary" @click="startNew"><Plus/> New Sellers Debit Note</button><button class="po-btn green" @click="exportExcel"><Download/> Export</button></div></header><div class="po-table-scroll"><table class="po-list-table"><thead><tr><th>A No.</th><th>Debit Note No.</th><th>Debit Note Date</th><th>Invoice No.</th><th>Invoice Date</th><th>PO No.</th><th>PO Date</th><th>Seller No.</th><th>Seller Name</th><th>Debit Note Amount</th><th>Reason</th><th>Status</th><th>Payment Status</th><th>View</th></tr></thead><tbody><tr v-for="(row,index) in paginated" :key="row.id"><td>{{ (page-1)*perPage+index+1 }}</td><td><button class="po-link" @click="openNote(row)">{{ row.debit_note_no }}</button></td><td>{{ dateLabel(row.debit_note_date) }}</td><td>{{ inv(row).invoice_no }}</td><td>{{ dateLabel(inv(row).invoice_date) }}</td><td>{{ inv(row).po_no }}</td><td>{{ dateLabel(inv(row).purchase_order?.po_date) }}</td><td>{{ inv(row).seller_no }}</td><td>{{ inv(row).seller_name }}</td><td class="po-number">{{ money(row.total) }}</td><td>{{ row.reason }}</td><td><span class="po-pill" :class="slug(row.status)">{{ row.status }}</span></td><td><span class="po-pill" :class="slug(row.settlement_status)">{{ row.settlement_status }}</span></td><td><button class="po-btn compact" @click="openNote(row)"><Eye/> View</button></td></tr><tr v-if="!paginated.length"><td colspan="14" class="po-empty">No seller debit notes found.</td></tr></tbody></table></div><footer class="po-pagination"><span>Showing {{ filtered.length?(page-1)*perPage+1:0 }} to {{ Math.min(page*perPage,filtered.length) }} of {{ filtered.length }} entries</span><div class="po-actions"><button class="po-icon" :disabled="page===1" @click="page--"><ChevronLeft/></button><b>{{ page }} / {{ pages }}</b><button class="po-icon" :disabled="page===pages" @click="page++"><ChevronRight/></button></div></footer><div class="po-action-bar"><b>Action Bar:</b><button class="po-btn primary" @click="printPage"><Printer/> Print</button><button class="po-btn green" @click="savePdf"><FileDown/> Save PDF</button><button class="po-btn" @click="emailNote"><Mail/> Email</button></div></section>
    </template>
    <div v-else class="po-workspace"><section class="po-document"><header class="po-document-head"><div class="po-heading"><FileMinus2/><h2>Seller Debit Note</h2></div><div class="po-actions"><b>{{ form.debit_note_no||'New debit note' }}</b><span class="po-pill" :class="slug(form.status)">{{ form.status }}</span><button class="po-icon" @click="printPage"><Printer/></button><button class="po-icon" @click="emailNote"><Mail/></button></div></header><div class="po-document-body">
      <div class="po-details-grid"><section><h3>Seller</h3><Field label="Seller No." :model-value="source.seller_no"/><Field label="Company Name" :model-value="source.seller_name"/><Field v-for="field in sellerFields" :key="field.key" :label="field.label" :model-value="source.seller_details?.[field.key]" :multiline="field.key==='address'"/></section><section><h3>Requested By</h3><Field label="Department" :model-value="source.department"/><Field label="Contact Person" :model-value="source.requested_by"/><Field v-for="field in requesterFields" :key="field.key" :label="field.label" :model-value="source.requester_details?.[field.key]" :multiline="field.key==='address'"/><Field label="Project" :model-value="source.project"/></section><section><h3>Debit Note Details</h3><div v-if="editing" class="po-field"><label>Invoice</label><i>:</i><select v-model="form.purchase_invoice_id" @change="applyInvoice"><option :value="null" disabled>Select invoice</option><option v-for="x in invoices" :key="x.id" :value="x.id">{{ x.invoice_no }} - {{ x.seller_name }}</option></select></div><Field v-else label="Invoice No." :model-value="source.invoice_no"/><Field label="PO No." :model-value="source.po_no"/><Field label="Debit Note No." v-model="form.debit_note_no" :editable="editing"/><Field label="Debit Note Date" v-model="form.debit_note_date" :editable="editing" type="date" :display-value="dateLabel(form.debit_note_date)"/><Field label="Due Date" v-model="form.due_date" :editable="editing" type="date" :display-value="dateLabel(form.due_date)"/><Field label="Invoice Date" :model-value="dateLabel(source.invoice_date)"/><Field label="Currency" :model-value="source.currency_code"/><Field label="Status" :model-value="form.status"/><Field label="Payment Term" :model-value="source.payment_term"/><Field label="Payment Method" :model-value="source.payment_method"/></section></div>
      <section class="po-items"><div v-if="editing" class="po-section-head"><h3>Debit Adjustments</h3><button class="po-btn compact primary" @click="addItem"><Plus/> Add adjustment</button></div><div class="po-table-scroll"><table><thead><tr><th>Item / Service</th><th>Code</th><th>UOM</th><th>Qty</th><th>Debit Rate</th><th>Subtotal</th><th>Sales Tax</th><th>Total</th><th v-if="editing"></th></tr></thead><tbody><tr v-for="(item,index) in form.items" :key="index"><td><input v-if="editing" v-model="item.name"><span v-else>{{ item.name }}</span></td><td><input v-if="editing" v-model="item.code"><span v-else>{{ item.code||'-' }}</span></td><td><input v-if="editing" v-model="item.uom"><span v-else>{{ item.uom }}</span></td><td><input v-if="editing" v-model.number="item.quantity" type="number" min="0.01" step="0.01"><span v-else>{{ money(item.quantity) }}</span></td><td><input v-if="editing" v-model.number="item.cost_rate" type="number" min="0" step="0.01"><span v-else>{{ money(item.cost_rate) }}</span></td><td>{{ money(lineSubtotal(item)) }}</td><td><input v-if="editing" v-model.number="item.sales_tax" type="number" min="0" step="0.01"><span v-else>{{ money(item.sales_tax) }}</span></td><td>{{ money(lineTotal(item)) }}</td><td v-if="editing"><button class="po-icon danger" @click="form.items.splice(index,1)"><Trash2/></button></td></tr><tr v-if="!form.items.length"><td :colspan="editing?9:8" class="po-empty">No adjustments added.</td></tr></tbody><tfoot><tr><th colspan="5">Total</th><th>{{ money(subtotal) }}</th><th>{{ money(tax) }}</th><th>{{ money(total) }}</th><th v-if="editing"></th></tr></tfoot></table></div></section>
      <div class="po-bottom-grid"><section><h3>Reason &amp; Notes</h3><Field label="Reason" v-model="form.reason" :editable="editing" :options="reasons"/><textarea v-if="editing" v-model="form.notes" rows="4"/><p v-else class="po-terms">{{ form.notes||'-' }}</p><Field label="Created By" :model-value="form.creator?.name"/><Field label="Created Date" :model-value="dateTimeLabel(form.created_at)"/></section><section><h3>Invoice Information</h3><Field label="Original Invoice" :model-value="source.invoice_no"/><Field label="Original Total" :model-value="money(source.total)"/><Field label="Delivery Location" :model-value="source.delivery_location"/><Field label="Seller Contact" :model-value="source.seller_details?.contact_person"/><Field label="Seller Phone" :model-value="source.seller_details?.phone"/></section><section class="po-totals"><Field label="Sub Total" :model-value="money(subtotal)"/><Field label="Sales Tax" :model-value="money(tax)"/><Field label="Settled" :model-value="money(form.settled)"/><div><span>Debit Note Total ({{ source.currency_code||'CAD' }})</span><strong>{{ money(total) }}</strong></div><div><span>Open Balance</span><strong>{{ money(balance) }}</strong></div></section></div><section v-if="form.attachments.length" class="po-attachments"><h3>Attachments</h3><button v-for="file in form.attachments" :key="file.id" class="po-btn compact" @click="downloadAttachment(file)"><Paperclip/> {{ file.name }}</button></section>
    </div><footer class="po-document-footer"><div class="po-actions"><button class="po-btn" @click="startNew"><Plus/> New</button><button class="po-btn" :disabled="editing||Number(form.settled)>0" @click="editing=true"><Pencil/> Edit</button><button class="po-btn danger" :disabled="!form.id||Number(form.settled)>0" @click="deleteNote"><Trash2/> Delete</button><button class="po-btn primary" :disabled="!editing" @click="saveNote"><Save/> Save</button><button v-if="editing" class="po-btn" @click="cancel"><X/> Cancel</button><button class="po-btn" @click="printPage"><Printer/> Print</button><button class="po-btn" @click="savePdf"><FileDown/> Save PDF</button><button class="po-btn green" :disabled="!canDecide" @click="workflow('approve')"><Check/> Approve</button><button class="po-btn danger" :disabled="!canDecide" @click="workflow('reject')"><X/> Reject</button></div><div class="po-actions"><button class="po-btn green" :disabled="!canSettle" @click="openSettlement"><BadgeDollarSign/> Record Settlement</button><button class="po-btn" :disabled="!canClose" @click="workflow('close')"><CircleCheckBig/> Close Note</button><button class="po-btn" :disabled="!form.id" @click="fileInput.click()"><Paperclip/> Attach File</button><input ref="fileInput" class="po-hidden" type="file" @change="upload"><button class="po-btn" :disabled="!form.id" @click="modal='audit'"><History/> Audit Log</button><button class="po-btn" :disabled="!canSubmit" @click="workflow('submit')"><Send/> Send for Approval</button><button class="po-btn green" @click="exportExcel"><FileSpreadsheet/> Export Excel</button></div></footer></section>
    <aside class="po-sidebar"><section><h3>Transaction Tracker</h3><div class="po-table-scroll"><table class="po-tracker"><thead><tr><th>Doc. Type</th><th>No.</th><th>Date</th><th>Total</th></tr></thead><tbody><tr><td>Purchase Order</td><td>{{ source.po_no||'-' }}</td><td>{{ dateLabel(source.purchase_order?.po_date) }}</td><td>{{ money(source.total) }}</td></tr><tr><td>Purchase Invoice</td><td>{{ source.invoice_no||'-' }}</td><td>{{ dateLabel(source.invoice_date) }}</td><td>{{ money(source.total) }}</td></tr><tr><td>Seller Debit Note</td><td>{{ form.debit_note_no||'-' }}</td><td>{{ dateLabel(form.debit_note_date) }}</td><td>-{{ money(total) }}</td></tr><tr v-for="x in form.settlements" :key="x.id"><td>Settlement</td><td>{{ x.settlement_no }}</td><td>{{ dateLabel(x.settlement_date) }}</td><td>{{ money(x.amount) }}</td></tr></tbody><tfoot><tr><th>Balance</th><th colspan="2">{{ source.currency_code }}</th><th>{{ money(balance) }}</th></tr></tfoot></table></div></section><section><h3>Current Debit Note</h3><Field label="Debit Note No." :model-value="form.debit_note_no"/><Field label="Invoice No." :model-value="source.invoice_no"/><Field label="PO No." :model-value="source.po_no"/><Field label="Date" :model-value="dateLabel(form.debit_note_date)"/><Field label="Reason" :model-value="form.reason"/><Field label="Status" :model-value="form.status"/><Field label="Payment Status" :model-value="form.settlement_status"/></section></aside></div>
    <div v-if="modal" class="po-modal-backdrop" @click.self="modal=''"> <section class="po-modal"><header><h2>{{ modal==='settlement'?'Record Debit Note Settlement':'Debit Note Audit Log' }}</h2><button class="po-icon" @click="modal=''"><X/></button></header><div v-if="modalError" class="po-alert error">{{ modalError }}</div><form v-if="modal==='settlement'" @submit.prevent="settle"><Field label="Settlement No." v-model="settlementForm.settlement_no" editable/><Field label="Date" v-model="settlementForm.settlement_date" editable type="date"/><Field label="Amount" v-model="settlementForm.amount" editable type="number"/><Field label="Method" v-model="settlementForm.method" editable/><Field label="Reference" v-model="settlementForm.reference" editable/><Field label="Notes" v-model="settlementForm.notes" editable multiline/><button class="po-btn green"><BadgeDollarSign/> Record Settlement</button></form><table v-else><thead><tr><th>Date</th><th>User</th><th>Action</th><th>Details</th></tr></thead><tbody><tr v-for="x in form.activities" :key="x.id"><td>{{ dateTimeLabel(x.created_at) }}</td><td>{{ x.actor }}</td><td>{{ x.action }}</td><td>{{ details(x.changes) }}</td></tr></tbody></table></section></div>
  </main></AccountLayout>
</template>
<script setup>
import {computed,onMounted,ref,watch} from 'vue'; import {FileMinus2,Search,ArrowLeft,RotateCcw,Plus,Download,Eye,ChevronLeft,ChevronRight,Printer,FileDown,Mail,Pencil,Trash2,Save,X,Check,BadgeDollarSign,CircleCheckBig,Paperclip,History,Send,FileSpreadsheet,WalletCards,BadgeCheck,Clock,CircleX} from 'lucide-vue-next'; import AccountLayout from '../components/AccountLayout.vue'; import Field from '../components/PurchaseOrderField.vue'; import client from '../api/client'; import {roundMoney,lineSubtotal,lineTotal,today,money,dateLabel,dateTimeLabel} from '../utils/purchaseOrders'
const rows=ref([]),invoices=ref([]),view=ref('list'),form=ref({}),editing=ref(false),busy=ref(false),error=ref(''),notice=ref(''),modal=ref(''),modalError=ref(''),settlementForm=ref({}),fileInput=ref(null),page=ref(1),perPage=ref(15);const statuses=['Draft','Pending','Approved','Rejected','Closed'],settlementStatuses=['Open','Partial','Paid'],reasons=['Price Difference','Wrong Items','Quality Issue','Damaged Items','Short Quantity','Service Deficiency','Other'];const sellerFields=[{key:'contact_person',label:'Contact Person'},{key:'phone',label:'Phone'},{key:'email',label:'Email'},{key:'address',label:'Address'},{key:'tax_number',label:'Tax Number'}],requesterFields=[{key:'phone',label:'Phone'},{key:'email',label:'Email'},{key:'company_name',label:'Company Name'},{key:'address',label:'Address'}];const initialFilters=()=>({search:'',from:'',to:'',seller:'',status:'',settlement:'',department:'',project:''}),filters=ref(initialFilters()),blank=()=>({id:null,debit_note_no:'',purchase_invoice_id:null,debit_note_date:today(),due_date:'',status:'Draft',settlement_status:'Open',reason:'',settled:0,items:[],notes:'',settlements:[],activities:[],attachments:[],purchase_invoice:null})
const inv=x=>x.purchase_invoice||{},source=computed(()=>inv(form.value)),slug=x=>String(x||'').toLowerCase().replace(/\s+/g,'-'),unique=x=>[...new Set(x.filter(Boolean))].sort(),sellerNames=computed(()=>unique(rows.value.map(x=>inv(x).seller_name))),departments=computed(()=>unique(rows.value.map(x=>inv(x).department))),projects=computed(()=>unique(rows.value.map(x=>inv(x).project)));const filtered=computed(()=>rows.value.filter(x=>{const f=filters.value,i=inv(x),q=f.search.toLowerCase(),d=String(x.debit_note_date).slice(0,10);return(!q||[x.debit_note_no,i.invoice_no,i.po_no,i.seller_name].some(v=>String(v||'').toLowerCase().includes(q)))&&(!f.seller||i.seller_name===f.seller)&&(!f.status||x.status===f.status)&&(!f.settlement||x.settlement_status===f.settlement)&&(!f.department||i.department===f.department)&&(!f.project||i.project===f.project)&&(!f.from||d>=f.from)&&(!f.to||d<=f.to)})),pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/perPage.value))),paginated=computed(()=>filtered.value.slice((page.value-1)*perPage.value,page.value*perPage.value));const sum=x=>x.reduce((s,r)=>s+Number(r.total),0),currency=x=>x[0]?.purchase_invoice?.currency_code||'CAD',metrics=computed(()=>[{label:'Total Debit Notes',rows:filtered.value,icon:WalletCards,tone:'blue'},{label:'Total Approved',rows:filtered.value.filter(x=>x.status==='Approved'),icon:BadgeCheck,tone:'green'},{label:'Total Pending',rows:filtered.value.filter(x=>x.status==='Pending'),icon:Clock,tone:'amber'},{label:'Total Rejected',rows:filtered.value.filter(x=>x.status==='Rejected'),icon:CircleX,tone:'red'},{label:'Total Closed',rows:filtered.value.filter(x=>x.status==='Closed'),icon:FileMinus2,tone:'purple'}]);const subtotal=computed(()=>roundMoney((form.value.items||[]).reduce((s,x)=>s+lineSubtotal(x),0))),tax=computed(()=>roundMoney((form.value.items||[]).reduce((s,x)=>s+Number(x.sales_tax||0),0))),total=computed(()=>roundMoney(subtotal.value+tax.value)),balance=computed(()=>roundMoney(total.value-Number(form.value.settled||0))),canSubmit=computed(()=>form.value.id&&!editing.value&&form.value.status==='Draft'),canDecide=computed(()=>form.value.id&&!editing.value&&['Draft','Pending'].includes(form.value.status)),canSettle=computed(()=>form.value.id&&!editing.value&&form.value.status==='Approved'&&balance.value>0),canClose=computed(()=>form.value.id&&form.value.status==='Approved'&&balance.value<=0)
const apiError=e=>Object.values(e.response?.data?.errors||{})[0]?.[0]||e.response?.data?.message||e.message;async function all(url){let p=1,last=1,out=[];do{const{data}=await client.get(url,{params:{per_page:100,page:p}}),body=data.data;out.push(...(body?.data||body||[]));last=body?.last_page||1;p++}while(p<=last);return out}async function load(){[rows.value,invoices.value]=await Promise.all([all('/seller-debit-notes'),all('/purchase-invoices')])}function normalize(x){const b=blank();return{...b,...x,purchase_invoice_id:x.purchase_invoice_id?Number(x.purchase_invoice_id):null,debit_note_date:String(x.debit_note_date||today()).slice(0,10),due_date:String(x.due_date||'').slice(0,10),items:(x.items||[]).map(i=>({...i})),settlements:x.settlements||[],activities:x.activities||[],attachments:x.attachments||[]}}
function startNew(){form.value=blank();editing.value=true;view.value='detail'}async function openNote(x){busy.value=true;try{const{data}=await client.get('/seller-debit-notes/'+x.id);form.value=normalize(data.data);editing.value=false;view.value='detail'}catch(e){error.value=apiError(e)}finally{busy.value=false}}function back(){view.value='list';editing.value=false}async function cancel(){form.value.id?await openNote(form.value):back()}function applyInvoice(){const i=invoices.value.find(x=>x.id===Number(form.value.purchase_invoice_id));if(!i)return;form.value.purchase_invoice=i;form.value.due_date=String(i.due_date||'').slice(0,10);form.value.items=[]}function addItem(){const x=source.value.items?.[0]||{};form.value.items.push({invoice_item_index:0,name:x.name?x.name+' adjustment':'',code:x.code||'',uom:x.uom||'PCS',quantity:1,cost_rate:0,sales_tax:0})}
async function saveNote(){if(!form.value.purchase_invoice_id||!form.value.reason||!form.value.items.length){error.value='Select an invoice, reason, and add an adjustment.';return}busy.value=true;try{const{data}=form.value.id?await client.put('/seller-debit-notes/'+form.value.id,form.value):await client.post('/seller-debit-notes',form.value);form.value=normalize(data.data);editing.value=false;await load();notice.value='Seller debit note saved.'}catch(e){error.value=apiError(e)}finally{busy.value=false}}async function workflow(action){try{const{data}=await client.post('/seller-debit-notes/'+form.value.id+'/workflow',{action});form.value=normalize(data.data);await load();notice.value='Debit note '+form.value.status.toLowerCase()+'.'}catch(e){error.value=apiError(e)}}async function deleteNote(){if(!confirm('Delete '+form.value.debit_note_no+'?'))return;try{await client.delete('/seller-debit-notes/'+form.value.id);await load();back()}catch(e){error.value=apiError(e)}}function openSettlement(){settlementForm.value={settlement_no:'DSET-'+String(Date.now()).slice(-6),settlement_date:today(),amount:balance.value,method:source.value.payment_method||'',reference:'',notes:''};modal.value='settlement'}async function settle(){try{const{data}=await client.post('/seller-debit-notes/'+form.value.id+'/settlements',settlementForm.value);form.value=normalize(data.data);await load();modal.value='';notice.value='Settlement recorded.'}catch(e){modalError.value=apiError(e)}}
async function upload(e){const file=e.target.files[0];if(!file)return;const body=new FormData();body.append('file',file);try{const{data}=await client.post('/seller-debit-notes/'+form.value.id+'/attachments',body);form.value=normalize(data.data)}catch(x){error.value=apiError(x)}finally{e.target.value=''}}async function downloadAttachment(f){const{data}=await client.get('/seller-debit-notes/'+form.value.id+'/attachments/'+f.id,{responseType:'blob'});download(data,f.name)}function download(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}function details(v){try{return Object.entries(typeof v==='string'?JSON.parse(v):v||{}).map(([k,x])=>k+': '+x).join(', ')}catch{return''}}function printPage(){window.print()}async function exportExcel(){const{default:ExcelJS}=await import('exceljs'),b=new ExcelJS.Workbook(),s=b.addWorksheet('Seller Debit Notes');s.addRow(['Debit Note','Date','Invoice','PO','Seller','Amount','Reason','Status','Payment Status']);filtered.value.forEach(x=>{const i=inv(x);s.addRow([x.debit_note_no,dateLabel(x.debit_note_date),i.invoice_no,i.po_no,i.seller_name,Number(x.total),x.reason,x.status,x.settlement_status])});s.columns.forEach(x=>x.width=22);download(new Blob([await b.xlsx.writeBuffer()]),'seller-debit-notes.xlsx')}async function savePdf(){const{default:jsPDF}=await import('jspdf'),p=new jsPDF();p.setFontSize(18);p.text(view.value==='list'?'Sellers Debit Note List':'Seller Debit Note '+form.value.debit_note_no,15,18);p.setFontSize(10);let y=30;(view.value==='list'?filtered.value:form.value.items).forEach(x=>{p.text(view.value==='list'?[x.debit_note_no,inv(x).seller_name,money(x.total),x.status].join(' | '):[x.name,x.quantity,money(lineTotal(x))].join(' | '),15,y);y+=7});p.save('seller-debit-notes.pdf')}function emailNote(){const subject='Seller Debit Note '+(form.value.debit_note_no||''),body=subject+'\nInvoice: '+(source.value.invoice_no||'')+'\nSeller: '+(source.value.seller_name||'')+'\nAmount: '+money(total.value);window.location.href='mailto:'+encodeURIComponent(source.value.seller_details?.email||'')+'?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(body)}watch([filters,perPage],()=>page.value=1,{deep:true});watch(pages,x=>page.value=Math.min(page.value,x));onMounted(async()=>{busy.value=true;try{await load()}catch(e){error.value=apiError(e)}finally{busy.value=false}})
</script><style src="../assets/purchase-orders.css"></style>
